112	/* LRADC_INTC / LRADC_INTS 位域（本驱动只用通道 0） */
113	#define CHAN0_KEYUP_IRQ		BIT(4)
114	#define CHAN0_ALRDY_HOLD_IRQ	BIT(3)
115	#define CHAN0_HOLD_IRQ		BIT(2)
116	#define CHAN0_KEYDOWN_IRQ	BIT(1)
117	#define CHAN0_DATA_IRQ		BIT(0)
