119	/* 6 bit ADC，满量程 63 */
120	#define LRADC_DATA_MASK		0x3f
121	#define LRADC_FULL_SCALE	63
122	
123	/* 本板参考电压：compatible 后缀 "keyboard_1350mv" */
124	#define LRADC_DEFAULT_VREF_MV	1350
