132	/**
133	 * struct wn_lradc_key - 一个按键的 DT 描述
134	 * @voltage_mv: DT 里写的标称电压（毫伏）
135	 * @keycode:    linux,input-event-codes.h 里的 KEY_* 码
136	 * @raw:        由 voltage_mv 换算出的 6bit 期望码值（四舍五入，便于日志对照）
137	 */
138	struct wn_lradc_key {
139		u32 voltage_mv;
140		u32 keycode;
141		u32 raw;
142	};
143	
144	/**
145	 * struct wn_lradc - 驱动私有状态
146	 * @dev:        设备指针
147	 * @base:       ioremap 后的寄存器基址
148	 * @clk:        lradc 时钟
149	 * @rst:        复位控制（可选）
150	 * @irq:        中断号
151	 * @vref_mv:    参考电压
152	 * @keys:       按键表
153	 * @nr_keys:    按键个数
154	 * @lock:       保护 @cur_keycode 与统计计数（中断与 debugfs 并发访问）
155	 * @cur_keycode: 当前按下的键码，0 表示无键按下
156	 * @is_open:    ADC 是否已使能
157	 * @stat_irq:       中断总次数
158	 * @stat_keydown:   键按下事件次数
159	 * @stat_keyup:     键抬起事件次数
160	 * @stat_unknown:   中断里判不出源的次数
161	 * @stat_unmatched: 有电压但匹配不到任何键的次数
162	 * @last_raw:   最近一次读到的 DATA0 原始值
163	 * @last_mv:    最近一次换算出的电压
164	 * @dbg_dir:    debugfs 目录
165	 */
166	struct wn_lradc {
167		struct device *dev;
168		void __iomem *base;
169		struct clk *clk;
170		struct reset_control *rst;
171		int irq;
172		u32 vref_mv;
173	
174		struct wn_lradc_key keys[LRADC_MAX_KEYS];
175		u32 nr_keys;
176	
177		spinlock_t lock;
178		u32 cur_keycode;
179	
180		bool is_open;
181	
182		u64 stat_irq;
183		u64 stat_keydown;
184		u64 stat_keyup;
185		u64 stat_unknown;
186		u64 stat_unmatched;
187		u32 last_raw;
188		u32 last_mv;
189	
190		/* 最近一次「中断通路自检」的结果，见 wn_lradc_dbg_selftest_write() */
191		u64 selftest_irqs;
192		u32 selftest_raw;
193		bool selftest_done;
194	
195		struct dentry *dbg_dir;
196	};
197	
198	/* ------------------------------------------------------------------ */
199	/* 寄存器访问                                                          */
200	/* ------------------------------------------------------------------ */
201	
202	static inline u32 wn_lradc_read(struct wn_lradc *lradc, u32 reg)
203	{
204		return readl(lradc->base + reg);
205	}
206	
207	static inline void wn_lradc_write(struct wn_lradc *lradc, u32 reg, u32 val)
208	{
209		writel(val, lradc->base + reg);
210	}
211	
212	/*
213	 * 6bit 原始码 → 毫伏。
214	 * 与 mainline 的 val * vref / 63 等价，只是把顺序改成先乘后除以免整数截断。
215	 */
216	static u32 wn_lradc_raw_to_mv(struct wn_lradc *lradc, u32 raw)
217	{
218		return raw * lradc->vref_mv / LRADC_FULL_SCALE;
219	}
220	
221	/*
222	 * 在按键表里找与实测电压最接近的一项。
223	 * 返回键索引，找不到返回 -ENOENT。
224	 *
225	 * 语义与 mainline 一致：取绝对差最小者，而不是区间判定。
226	 * 这样 DT 里标的电压有偏差也不会整键失效。
227	 */
228	static int wn_lradc_match_key(struct wn_lradc *lradc, u32 mv, u32 *out_keycode)
229	{
230		u32 i, best_diff = U32_MAX;
231		int best = -ENOENT;
232	
233		for (i = 0; i < lradc->nr_keys; i++) {
234			u32 diff = abs((int)lradc->keys[i].voltage_mv - (int)mv);
235	
236			if (diff < best_diff) {
237				best_diff = diff;
238				best = (int)i;
239			}
240		}
241	
242		if (best >= 0 && out_keycode)
243			*out_keycode = lradc->keys[best].keycode;
244	
245		return best;
246	}
247	
248	/* ------------------------------------------------------------------ */
249	/* 中断处理                                                            */
250	/* ------------------------------------------------------------------ */
251	
252	/*
253	 * 中断上下文约束（驱动开发必考点）：
254	 *   - 不能睡眠：不能调用 kmalloc(GFP_KERNEL)、mutex_lock、copy_to_user 等
255	 *   - 不能做长耗时操作
256	 *   本 handler 只做 readl/writel + 内存写，完全满足。
257	 *
258	 * 共享状态的保护：
259	 *   @cur_keycode 会被这里的「中断上下文」与 debugfs 的「进程上下文」同时读，
260	 *   所以用 spinlock 而非 mutex（mutex 不能用在中断里）。
261	 */
262	static irqreturn_t wn_lradc_irq(int irq, void *dev_id)
263	{
264		struct wn_lradc *lradc = dev_id;
265		unsigned long flags;
266		u32 ints, raw, mv, keycode = 0;
267		bool reported = false;
268	
269		/* 先读中断状态；判不出源就直接返回 IRQ_NONE，让内核统计 spurious */
270		ints = wn_lradc_read(lradc, LRADC_INTS);
271		if (!(ints & (CHAN0_KEYUP_IRQ | CHAN0_KEYDOWN_IRQ |
272			      CHAN0_HOLD_IRQ | CHAN0_ALRDY_HOLD_IRQ |
273			      CHAN0_DATA_IRQ))) {
274			spin_lock_irqsave(&lradc->lock, flags);
275			lradc->stat_unknown++;
276			lradc->stat_irq++;
277			spin_unlock_irqrestore(&lradc->lock, flags);
278			return IRQ_NONE;
279		}
280	
281		spin_lock_irqsave(&lradc->lock, flags);
282		lradc->stat_irq++;
283		spin_unlock_irqrestore(&lradc->lock, flags);
284	
285		/* 抬起：上报 release 并清掉缓存键码 */
286		if (ints & CHAN0_KEYUP_IRQ) {
287			spin_lock_irqsave(&lradc->lock, flags);
288			keycode = lradc->cur_keycode;
